-- composition of rule kernels BloomFilter x GroupByOrder (sqlite), template graft_exists
SELECT '{"k": 2, "a": [0]}' AS c0 FROM (SELECT * FROM tp WHERE EXISTS (SELECT 1 FROM (WITH t(g, x) AS ( SELECT 1, '9007199254740994abc' ) SELECT NULL FROM t GROUP BY g ORDER BY g) AS kb) OR NOT EXISTS (SELECT 1 FROM (WITH t(g, x) AS ( SELECT 1, '9007199254740994abc' ) SELECT NULL FROM t GROUP BY g ORDER BY g) AS kb)) AS a1 WHERE ((a1.c1, CASE WHEN FALSE THEN TRUE ELSE (CAST(1 AS INTEGER) IN (SELECT CAST(100 AS INTEGER) AS c0)) END) <> (a1.c1, TRUE)) GROUP BY a1.c0, a1.c1;
